/*
 * A078255  Squares with distinct digits. To make an infinite sequence, we
 *          also include m-digit numbers in which each digit occurs no more
 *          than ceiling(m/10) times.
 * https://oeis.org/A078255
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, nonn, easy
 * Formula:   a(n) is the n-th square (including 0^2) that satisfies the
 *            condition: for an m‑digit square, each decimal digit appears at
 *            most ceil(m/10) times. The sequence is generated by sequentially
 *            testing squares for this property
 * Range:     u8 n <= 12, u16 n <= 106, u32 n <= 566, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   digit_frequencies, digit_len
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include "../utils/digit_len.h"
#include "../utils/digit_frequencies.h"

seq_t a(idx_t n)
{
    /* n is 1‑based.  If n==0 we return 0, though never called. */
    if (n == 0) {
        return (seq_t)0;
    }

    idx_t found = 0;
    for (idx_t i = 0ULL;; ++i) {
        seq_t sq = (seq_t)i * (seq_t)i;     /* compute the square */

        /* Count the decimal digits of sq. */
        int m = digit_len(sq);              /* number of digits */
        int max_per_digit = (m + 9) / 10;   /* ceil(m/10) */

        unsigned int freq[10];
        digit_frequencies(sq, freq);

        bool ok = true;
        for (int d = 0; d < 10; ++d) {
            if (freq[d] > max_per_digit) {
                ok = false;
                break;
            }
        }

        if (ok) {
            ++found;
            if (found == n) {
                return sq;
            }
        }
    }
}
